function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(item);
  }
  return result;
}

module.exports = { uniqueBy };

const test = require("node:test");
const assert = require("node:assert/strict");
const { uniqueBy } = require("../src/solution.cjs");

test("keeps the first item for each duplicate key in input order", () => {
  const items = [
    { id: 2, v: "a" },
    { id: 1, v: "b" },
    { id: 2, v: "c" },
    { id: 3, v: "d" },
    { id: 1, v: "e" },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.id), [
    { id: 2, v: "a" },
    { id: 1, v: "b" },
    { id: 3, v: "d" },
  ]);
});

test("treats number 1 and string \"1\" as different keys", () => {
  const items = [1, "1", 1, "1", 2, "2"];
  assert.deepEqual(uniqueBy(items, (x) => x), [1, "1", 2, "2"]);
});

test("mixed key types: keyOf result decides identity, not the item", () => {
  const items = [
    { k: 1 },
    { k: "1" },
    { k: 1.0 },
    { k: "1" },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.k), [{ k: 1 }, { k: "1" }]);
});

test("\"__proto__\" and other prototype-like names are ordinary keys", () => {
  const items = ["__proto__", "constructor", "__proto__", "toString", "constructor"];
  assert.deepEqual(uniqueBy(items, (x) => x), ["__proto__", "constructor", "toString"]);
});

test("empty input returns a new empty array", () => {
  const items = [];
  const result = uniqueBy(items, (x) => x);
  assert.deepEqual(result, []);
  assert.notEqual(result, items);
});

test("does not mutate the input array or its items", () => {
  const items = Object.freeze([
    Object.freeze({ id: 1 }),
    Object.freeze({ id: 1 }),
    Object.freeze({ id: 2 }),
  ]);
  const snapshot = items.slice();
  const result = uniqueBy(items, (x) => x.id);
  assert.equal(items.length, 3);
  assert.deepEqual(items, snapshot);
  assert.notEqual(result, items);
  assert.equal(result[0], items[0]);
  assert.equal(result[1], items[2]);
});

test("calls keyOf once per item in order", () => {
  const seen = [];
  uniqueBy(["a", "b", "a"], (x) => {
    seen.push(x);
    return x;
  });
  assert.deepEqual(seen, ["a", "b", "a"]);
});

'use strict';

function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(item);
  }
  return result;
}

module.exports = { uniqueBy };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { uniqueBy } = require('../src/solution.cjs');

const byId = (item) => item.id;

test('keeps the first item for each duplicate key, in input order', () => {
  const items = [
    { id: 2, name: 'a' },
    { id: 1, name: 'b' },
    { id: 2, name: 'c' },
    { id: 3, name: 'd' },
    { id: 1, name: 'e' },
  ];
  assert.deepEqual(uniqueBy(items, byId), [
    { id: 2, name: 'a' },
    { id: 1, name: 'b' },
    { id: 3, name: 'd' },
  ]);
});

test('returns [] for empty input', () => {
  assert.deepEqual(uniqueBy([], byId), []);
});

test('returns a new array even when nothing is removed', () => {
  const items = [{ id: 1 }, { id: 2 }];
  const result = uniqueBy(items, byId);
  assert.notEqual(result, items);
  assert.deepEqual(result, items);
});

test('treats number 1 and string "1" as different keys', () => {
  const items = [
    { key: 1, name: 'number-a' },
    { key: '1', name: 'string-a' },
    { key: 1, name: 'number-b' },
    { key: '1', name: 'string-b' },
  ];
  assert.deepEqual(uniqueBy(items, (item) => item.key), [
    { key: 1, name: 'number-a' },
    { key: '1', name: 'string-a' },
  ]);
});

test('handles mixed number and string keys with no collisions across types', () => {
  const keys = [0, '0', 2, '2', 0, '2', 'x', 'x', 10, '10'];
  const result = uniqueBy(keys, (k) => k);
  assert.deepEqual(result, [0, '0', 2, '2', 'x', 10, '10']);
});

test('does not mutate the input array or its items', () => {
  const items = [{ id: 1, tag: 'a' }, { id: 1, tag: 'b' }, { id: 2, tag: 'c' }];
  const snapshot = structuredClone(items);
  uniqueBy(items, byId);
  assert.deepEqual(items, snapshot);
  assert.equal(items.length, 3);
});

test('treats "__proto__" and other Object.prototype names as ordinary keys', () => {
  const items = [
    { key: '__proto__', v: 1 },
    { key: 'constructor', v: 2 },
    { key: '__proto__', v: 3 },
    { key: 'toString', v: 4 },
    { key: 'constructor', v: 5 },
    { key: 'hasOwnProperty', v: 6 },
  ];
  assert.deepEqual(uniqueBy(items, (item) => item.key), [
    { key: '__proto__', v: 1 },
    { key: 'constructor', v: 2 },
    { key: 'toString', v: 4 },
    { key: 'hasOwnProperty', v: 6 },
  ]);
});

test('keeps all items when every key is unique', () => {
  const items = ['a', 'b', 'c'];
  assert.deepEqual(uniqueBy(items, (s) => s), ['a', 'b', 'c']);
});

function uniqueBy(items, keyOf) {
  const firstByKey = new Map();
  for (const item of items) {
    const key = keyOf(item);
    if (!firstByKey.has(key)) {
      firstByKey.set(key, item);
    }
  }
  return [...firstByKey.values()];
}

