const identity = (x) => x;

test("keeps the first item for each duplicate key, in input order", () => {
  const items = [
    { id: "b", n: 1 },
    { id: "a", n: 2 },
    { id: "b", n: 3 },
    { id: "c", n: 4 },
    { id: "a", n: 5 },
