test("returns the same item objects, not copies", () => {
  const first = { id: 1 };
  const result = uniqueBy([first, { id: 1 }], (x) => x.id);
  assert.equal(result.length, 1);
  assert.strictEqual(result[0], first);
});

test("treats number 1 and string \"1\" as different keys", () => {
