});

test("mixed key types keep first occurrence of each distinct key", () => {
  const items = [
    { k: 0 },
    { k: "0" },
    { k: 1 },
    { k: "1" },
    { k: 0 },
    { k: "1" },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.k), [
    { k: 0 },
    { k: "0" },
    { k: 1 },
    { k: "1" },
  ]);
});

test("does not mutate the input array or its items", () => {
  const items = [{ id: 2 }, { id: 1 }, { id: 2 }];
  const snapshot = JSON.parse(JSON.stringify(items));
  const copyOfArray = items.slice();
  const result = uniqueBy(items, (x) => x.id);
  assert.deepEqual(items, snapshot);
  assert.deepEqual(items, copyOfArray);
  assert.notStrictEqual(result, items);
});

