  uniqueBy([], () => {
    calls++;
    return 0;
  });
  assert.equal(calls, 0);
});

test("calls keyOf once per item", () => {
  let calls = 0;
  uniqueBy([1, 1, 2], (x) => {
    calls++;
    return x;
  });
  assert.equal(calls, 3);
});

