_ASCII_DIGITS = "0123456789"


def parse_port(text):
    if not isinstance(text, str):
        raise ValueError(f"port must be a string, got {type(text).__name__}")

    digits = text.strip(" ")
    if not digits or any(c not in _ASCII_DIGITS for c in digits):
        raise ValueError(f"invalid port: {text!r}")

    significant = digits.lstrip("0")
    if not significant or len(significant) > 5 or int(significant) > 65535:
        raise ValueError(f"port out of range 1-65535: {text!r}")

    return int(significant)

def parse_port(text):
    if not isinstance(text, str):
        raise ValueError("port must be a string")
    stripped = text.strip(" ")
    if not (stripped.isascii() and stripped.isdigit()):
        raise ValueError(f"invalid port: {text!r}")
    significant = stripped.lstrip("0")
    if not significant or len(significant) > 5:
        raise ValueError(f"port out of range 1-65535: {text!r}")
    port = int(significant)
    if port > 65535:
        raise ValueError(f"port out of range 1-65535: {text!r}")
    return port

