const defaultSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function retry(operation, options = {}) {
  const {
    attempts,
    delayMs = 0,
    sleep = defaultSleep,
    shouldRetry = () => true,
  } = options;

  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError(`attempts must be a positive integer, got ${String(attempts)}`);
  }

  return (async () => {
    for (let attempt = 1; ; attempt += 1) {
      try {
        return await operation();
      } catch (error) {
        if (attempt >= attempts || !shouldRetry(error)) {
          throw error;
        }
        await sleep(delayMs);
      }
    }
  })();
}

module.exports = { retry };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function fakeSleep(log) {
  const calls = [];
  const sleep = async (ms) => {
    calls.push(ms);
    log.push(`sleep:${ms}`);
    await Promise.resolve();
  };
  return { sleep, calls };
}

function failingThen(results) {
  let call = 0;
  const log = [];
  const operation = async () => {
    call += 1;
    log.push(`op:${call}`);
    const result = results[call - 1];
    if (result instanceof Error || (result && result.fail)) throw result.error ?? result;
    return result;
  };
  return { operation, log, get calls() { return call; } };
}

test('returns first successful value without sleeping', async () => {
  const log = [];
  const { sleep, calls } = fakeSleep(log);
  const op = failingThen(['ok']);

  const value = await retry(op.operation, { attempts: 3, delayMs: 10, sleep });

  assert.equal(value, 'ok');
  assert.equal(op.calls, 1);
  assert.deepEqual(calls, []);
});

test('retries until success and sleeps only between attempts', async () => {
  const log = [];
  const { sleep, calls } = fakeSleep(log);
  const err1 = new Error('first');
  const err2 = new Error('second');
  const op = failingThen([{ fail: true, error: err1 }, { fail: true, error: err2 }, 'done']);

  const value = await retry(op.operation, { attempts: 5, delayMs: 25, sleep });

  assert.equal(value, 'done');
  assert.equal(op.calls, 3);
  assert.deepEqual(calls, [25, 25]);
  assert.deepEqual(log, ['op:1', 'sleep:25', 'op:2', 'sleep:25', 'op:3']);
});

test('awaits sleep before the next attempt', async () => {
  const log = [];
  let releaseSleep;
  const sleep = (ms) => {
    log.push(`sleep:${ms}`);
    return new Promise((resolve) => {
      releaseSleep = () => {
        log.push('wake');
        resolve();
      };
    });
  };
  const op = failingThen([{ fail: true, error: new Error('x') }, 'ok']);

  const pending = retry(op.operation, { attempts: 2, delayMs: 5, sleep });
  await Promise.resolve();
  await Promise.resolve();
  assert.equal(op.calls, 1);
  releaseSleep();

  assert.equal(await pending, 'ok');
  assert.deepEqual(log, ['op:1', 'sleep:5', 'wake', 'op:2']);
});

