  const op = failingThen([{ fail: true, error: new Error('only') }]);

  await assert.rejects(retry(op.operation, { attempts: 1, delayMs: 50, sleep }));

  assert.equal(op.calls, 1);
  assert.deepEqual(calls, []);
});

test('retries operations that throw synchronously', async () => {
  const { sleep } = fakeSleep([]);
