  const operation = () => {
    call += 1;
    if (call < 2) throw new Error('sync');
    return 'sync-ok';
  };

  assert.equal(await retry(operation, { attempts: 2, delayMs: 1, sleep }), 'sync-ok');
  assert.equal(call, 2);
});

test('shouldRetry false stops immediately and rethrows that error', async () => {
  const log = [];
  const { sleep, calls } = fakeSleep(log);
  const fatal = new Error('fatal');
  const op = failingThen([{ fail: true, error: fatal }, 'never']);
  const seen = [];

  await assert.rejects(
    retry(op.operation, {
      attempts: 5,
      delayMs: 3,
      sleep,
      shouldRetry: (error) => {
        seen.push(error);
        return false;
      },
    }),
    (thrown) => thrown === fatal,
  );

  assert.equal(op.calls, 1);
  assert.deepEqual(calls, []);
  assert.deepEqual(seen, [fatal]);
});

test('shouldRetry gates each retry individually', async () => {
  const log = [];
  const { sleep, calls } = fakeSleep(log);
  const transient = new Error('transient');
  const fatal = new Error('fatal');
  const op = failingThen([
    { fail: true, error: transient },
    { fail: true, error: fatal },
    'unreached',
  ]);

  await assert.rejects(
    retry(op.operation, {
      attempts: 4,
      delayMs: 2,
      sleep,
      shouldRetry: (error) => error === transient,
    }),
    (thrown) => thrown === fatal,
  );

  assert.equal(op.calls, 2);
  assert.deepEqual(calls, [2]);
});

test('non-Error rejection values are passed through unchanged', async () => {
  const { sleep } = fakeSleep([]);
  const reason = { code: 'E_X' };
  const op = failingThen([{ fail: true, error: reason }, { fail: true, error: reason }]);

  await assert.rejects(
    retry(op.operation, { attempts: 2, delayMs: 0, sleep }),
    (thrown) => thrown === reason,
  );
});

test('attempts of 1 calls the operation once and never sleeps', async () => {
  const { sleep, calls } = fakeSleep([]);
  const op = failingThen([{ fail: true, error: new Error('once') }]);

  await assert.rejects(retry(op.operation, { attempts: 1, delayMs: 9, sleep }), /once/);

  assert.equal(op.calls, 1);
  assert.deepEqual(calls, []);
});

test('invalid attempts throw RangeError synchronously without calling the operation', () => {
  const invalid = [0, -1, 1.5, NaN, Infinity, '3', undefined, null];
  for (const attempts of invalid) {
    let called = false;
    assert.throws(
      () => retry(() => { called = true; }, { attempts, delayMs: 0, sleep: async () => {} }),
      RangeError,
      `attempts=${String(attempts)}`,
    );
