    for before, after in edges:
        successors[before].append(after)
        indegree[after] += 1

    queue = deque(node for node in nodes if indegree[node] == 0)
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for after in successors[node]:
            indegree[after] -= 1
            if indegree[after] == 0:
                queue.append(after)

    if len(order) != len(nodes):
        raise ValueError("graph contains a cycle")
    return order

