def names_of(rows):
    return [name for _, name in rows]


class SearchTests(unittest.TestCase):
    def setUp(self):
        self.conn = make_db(
            ["alice", "albert", "bob", "50% off", "50 off", "a_c", "abc", "a\\b", "axb"]
        )

    def test_prefix_match_is_sorted_by_name(self):
        self.assertEqual(names_of(search(self.conn, "al", 10)), ["albert", "alice"])

    def test_percent_in_prefix_is_literal(self):
        self.assertEqual(search(self.conn, "50%", 10), [(4, "50% off")])

    def test_underscore_in_prefix_is_literal(self):
        self.assertEqual(search(self.conn, "a_", 10), [(6, "a_c")])

    def test_backslash_in_prefix_is_literal(self):
        self.assertEqual(search(self.conn, "a\\", 10), [(8, "a\\b")])

    def test_backslash_before_percent_is_literal(self):
        conn = make_db(["a\\%", "a%", "a\\x"])
        self.assertEqual(names_of(search(conn, "a\\%", 10)), ["a\\%"])

    def test_sql_injection_is_treated_as_text(self):
        self.assertEqual(search(self.conn, "' OR '1'='1", 10), [])
        search(self.conn, "x'; DROP TABLE users; --", 10)
        self.assertEqual(names_of(search(self.conn, "alice", 10)), ["alice"])

    def test_empty_prefix_matches_all(self):
        self.assertEqual(len(search(self.conn, "", 100)), 9)

    def test_ties_are_ordered_by_id(self):
        conn = sqlite3.connect(":memory:")
        conn.execute("CREATE TABLE users (id INTEGER, name TEXT)")
        conn.executemany(
            "INSERT INTO users (id, name) VALUES (?, ?)",
            [(3, "sam"), (1, "sam"), (2, "sam")],
        )
        self.assertEqual([i for i, _ in search(conn, "sam", 10)], [1, 2, 3])

    def test_limit_is_applied(self):
        conn = make_db([f"u{i:03d}" for i in range(150)])
        self.assertEqual(len(search(conn, "u", 5)), 5)

    def test_limit_below_one_is_clamped_to_one(self):
        conn = make_db([f"u{i:03d}" for i in range(150)])
        self.assertEqual(len(search(conn, "u", 0)), 1)
        self.assertEqual(len(search(conn, "u", -5)), 1)

    def test_limit_above_hundred_is_clamped_to_hundred(self):
        conn = make_db([f"u{i:03d}" for i in range(150)])
        self.assertEqual(len(search(conn, "u", 1000)), 100)

    def test_bool_limit_is_rejected(self):
        for value in (True, False):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    search(self.conn, "a", value)

    def test_non_integer_limit_is_rejected(self):
        for value in ("5", 2.0, 1.5, None, [1]):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    search(self.conn, "a", value)

    def test_non_string_prefix_is_rejected(self):
        with self.assertRaises(TypeError):
            search(self.conn, 5, 10)


