def _parse_age(value, line_num):
    if not _AGE_PATTERN.fullmatch(value):
        raise ValueError(f"line {line_num}: age must be ASCII digits, got {value!r}")
    age = int(value)
    if age > _MAX_AGE:
        raise ValueError(f"line {line_num}: age {age} is outside 0..{_MAX_AGE}")
    return age

