import re

_HEADER = ["name", "age"]
_MAX_AGE = 130
_AGE_PATTERN = re.compile(r"[0-9]+")
_FIELD_PATTERN = re.compile(r'"((?:[^"]|"")*)"|([^",\r\n]*)')
_SEPARATOR_PATTERN = re.compile(r",|\r\n|\r|\n|\Z")


def read_people(text):
    records = _parse_records(text)
    if not records or records[0] != _HEADER:
        raise ValueError("header must be exactly name,age")
    people = []
    for record in records[1:]:
        if len(record) != 2:
            raise ValueError(f"expected 2 columns, got {len(record)}: {record!r}")
        name, age = record
        people.append({"name": name, "age": _parse_age(age)})
    return people


def _parse_records(text):
    records = []
    pos = 0
    while pos < len(text):
        record = []
        while True:
            match = _FIELD_PATTERN.match(text, pos)
            if match.group(1) is not None:
                record.append(match.group(1).replace('""', '"'))
            else:
                record.append(match.group(2))
            pos = match.end()
            separator = _SEPARATOR_PATTERN.match(text, pos)
            if separator is None:
                raise ValueError(f"invalid CSV quoting at offset {pos}")
            pos = separator.end()
            if separator.group() != ",":
                break
        records.append(record)
    return records


def _parse_age(field):
    if _AGE_PATTERN.fullmatch(field) is None:
        raise ValueError(f"age must contain only ASCII digits: {field!r}")
    age = int(field)
    if age > _MAX_AGE:
        raise ValueError(f"age must be between 0 and {_MAX_AGE}: {field!r}")
    return age

