import re

_HEADER = ["name", "age"]
_FIELD = re.compile(r'"((?:[^"]|"")*)"|([^",\r\n]*)')
_AGE = re.compile(r"[0-9]+")


def _parse_records(text):
    records = []
    pos = 0
    while pos < len(text):
        record = []
        while True:
            match = _FIELD.match(text, pos)
            if match.group(1) is not None:
                record.append(match.group(1).replace('""', '"'))
            else:
                record.append(match.group(2))
            pos = match.end()
            if pos == len(text):
                records.append(record)
                break
            if text[pos] == ",":
                pos += 1
            elif text.startswith("\r\n", pos):
                records.append(record)
                pos += 2
                break
            elif text[pos] in "\r\n":
                records.append(record)
                pos += 1
                break
            else:
                raise ValueError(f"malformed CSV quoting at offset {pos}")
    return records


def _parse_age(text):
    if not _AGE.fullmatch(text):
        raise ValueError(f"invalid age: {text!r}")
    age = int(text)
    if age > 130:
        raise ValueError(f"age out of range 0..130: {age}")
    return age


def read_people(text):
    records = _parse_records(text)
    if not records or records[0] != _HEADER:
        raise ValueError(f"expected header {','.join(_HEADER)}")
    people = []
    for record in records[1:]:
        if len(record) != 2:
            raise ValueError(f"expected 2 columns, got {len(record)}: {record!r}")
        name, age = record
        people.append({"name": name, "age": _parse_age(age)})
    return people

