import csv
import io

_HEADER = ["name", "age"]
_ASCII_DIGITS = frozenset("0123456789")
_MAX_AGE = 130


def read_people(text):
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        header = next(reader, None)
        if header != _HEADER:
            raise ValueError(f"expected header {_HEADER!r}, got {header!r}")
        people = []
        for row in reader:
            if len(row) != 2:
                raise ValueError(f"line {reader.line_num}: expected 2 columns, got {len(row)}")
            name, age = row
            people.append({"name": name, "age": _parse_age(age, reader.line_num)})
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from exc
    return people


def _parse_age(field, line):
    if not field or not all(char in _ASCII_DIGITS for char in field):
        raise ValueError(f"line {line}: age must be ASCII digits, got {field!r}")
    age = int(field)
    if age > _MAX_AGE:
        raise ValueError(f"line {line}: age must be at most {_MAX_AGE}, got {age}")
    return age

