function scripted(pages) {
  const calls = [];
  const fetchPage = async (cursor) => {
    calls.push(cursor);
    const page = pages[cursor];
    if (!page) throw new Error(`unexpected cursor: ${cursor}`);
    return page;
  };
  return { fetchPage, calls };
}

