  const fetchPage = async (cursor) => {
    calls.push(cursor);
    const key = cursor === null ? 'null' : `c:${cursor}`;
    if (!(key in pages)) throw new Error(`unexpected cursor ${key}`);
    const step = pages[key];
    if (step instanceof Error) throw step;
    return step;
  };
  return { fetchPage, calls };
}

test('collects items from every page in order, keeping duplicates', async () => {
  const { fetchPage, calls } = scripted({
    'null': { items: [1, 2, 2], next: 'a' },
    'c:a': { items: [2, 3], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), [1, 2, 2, 2, 3]);
  assert.deepEqual(calls, [null, 'a']);
});

