    'c:a': { items: [], next: 'b' },
    'c:b': { items: ['y'], next: null },
  });

  assert.deepEqual(await collectPages(fetchPage), ['x', 'y']);
  assert.deepEqual(calls, [null, 'a', 'b']);
});

