'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean' || typeof value === 'number') {
    return;
  }
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) {
      assertJsonLike(value[i]);
    }
    return;
  }
  if (!isPlainObject(value)) {
    throw new TypeError('mergeConfig: only JSON-like values are supported');
  }
  for (const name of Object.getOwnPropertyNames(value)) {
    if (UNSAFE_KEYS.has(name)) {
      throw new TypeError(`mergeConfig: unsafe key "${name}"`);
    }
  }
  for (const key of Object.keys(value)) {
    assertJsonLike(value[key]);
  }
}

function deepCopy(value) {
  if (Array.isArray(value)) {
    const out = new Array(value.length);
    for (let i = 0; i < value.length; i++) {
      out[i] = deepCopy(value[i]);
    }
    return out;
  }
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) {
      out[key] = deepCopy(value[key]);
    }
    return out;
  }
  return value;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return deepCopy(override);
  }
  const out = {};
  for (const key of Object.keys(base)) {
    out[key] = Object.prototype.hasOwnProperty.call(override, key)
      ? mergeValues(base[key], override[key])
      : deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!Object.prototype.hasOwnProperty.call(base, key)) {
      out[key] = deepCopy(override[key]);
    }
  }
  return out;
}

function mergeConfig(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    throw new TypeError('mergeConfig: base and override must be plain objects');
  }
  assertJsonLike(base);
  assertJsonLike(override);
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mergeConfig } = require('../src/solution.cjs');

function collectContainers(value, out = new Set()) {
  if (value !== null && typeof value === 'object') {
    out.add(value);
    for (const key of Object.keys(value)) {
      collectContainers(value[key], out);
    }
  }
  return out;
}

function assertNoSharedContainers(result, ...inputs) {
  const resultContainers = collectContainers(result);
  const inputContainers = new Set();
  for (const input of inputs) {
    collectContainers(input, inputContainers);
  }
  for (const container of resultContainers) {
    assert.equal(inputContainers.has(container), false, 'result shares an object or array with an input');
  }
}

