const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function deepCopyJsonValue(value, path) {
  if (value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return value;
  }

  if (Array.isArray(value)) {
    const copy = new Array(value.length);
    for (let index = 0; index < value.length; index++) {
      copy[index] = deepCopyJsonValue(value[index], `${path}[${index}]`);
    }
    return copy;
  }

  if (isPlainObject(value)) {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`Unsafe key "${key}" at ${path}`);
      }
    }
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopyJsonValue(value[key], `${path}.${key}`);
    }
    return copy;
  }

  throw new TypeError(`Unsupported value at ${path}: expected a JSON-like value`);
}

function mergeCopiedObjects(target, source) {
  for (const key of Object.keys(source)) {
    if (hasOwn(target, key) && isPlainObject(target[key]) && isPlainObject(source[key])) {
      target[key] = mergeCopiedObjects(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

function mergeConfig(base, override) {
  const baseCopy = deepCopyJsonValue(base, 'base');
  const overrideCopy = deepCopyJsonValue(override, 'override');

  if (isPlainObject(baseCopy) && isPlainObject(overrideCopy)) {
    return mergeCopiedObjects(baseCopy, overrideCopy);
  }
  return overrideCopy;
}

