function invalid(message) {
  return new RangeError(message);
}

function validate(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw invalid("total must be a nonnegative safe integer");
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw invalid("weights must be a nonempty array");
  }

  let sum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw invalid("each weight must be a positive safe integer");
    }
    sum += weight;
    if (!Number.isSafeInteger(sum)) {
      throw invalid("sum of weights must be a safe integer");
    }
    if (!Number.isSafeInteger(total * weight)) {
      throw invalid("total * weight must be a safe integer");
    }
  }
  return sum;
}

function splitCents(total, weights) {
  const sum = validate(total, weights);

  const shares = weights.map((weight, index) => {
    const product = total * weight;
    const remainder = product % sum;
    const quota = (product - remainder) / sum;
    return { index, quota, remainder };
  });

  let leftover = total;
  for (const share of shares) {
    leftover -= share.quota;
  }

  const byRemainder = [...shares].sort(
    (a, b) => b.remainder - a.remainder || a.index - b.index,
  );
  for (let i = 0; i < leftover; i++) {
    byRemainder[i].quota += 1;
  }

  return shares.map((share) => share.quota);
}

module.exports = { splitCents };

