function invalid(message) {
  return new RangeError(message);
}

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw invalid("total must be a nonnegative safe integer");
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw invalid("weights must be a nonempty array");
  }

  let weightSum = 0;
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw invalid(`weights[${i}] must be a positive safe integer`);
    }
    weightSum += w;
    if (!Number.isSafeInteger(weightSum)) {
      throw invalid("sum of weights must be a safe integer");
    }
    if (!Number.isSafeInteger(total * w)) {
      throw invalid(`total * weights[${i}] must be a safe integer`);
    }
  }

  const quotas = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const product = total * weights[i];
    const remainder = product % weightSum;
    quotas[i] = (product - remainder) / weightSum;
    remainders[i] = remainder;
    allocated += quotas[i];
  }

  let leftover = total - allocated;
  const order = weights.map((_, i) => i);
  order.sort((a, b) => remainders[b] - remainders[a] || a - b);
  for (let k = 0; leftover > 0; k++, leftover--) {
    quotas[order[k]] += 1;
  }

  return quotas;
}

