      throw new RangeError('weights must be positive safe integers');
    }
    sum += weight;
    if (!Number.isSafeInteger(sum)) {
      throw new RangeError('sum of weights must fit in the safe integer range');
    }
    if (!Number.isSafeInteger(total * weight)) {
      throw new RangeError('total * weight must fit in the safe integer range');
    }
  }

  const bigTotal = BigInt(total);
  const bigSum = BigInt(sum);
  const quotas = weights.map((weight) => {
    const product = bigTotal * BigInt(weight);
    return { floor: product / bigSum, remainder: product % bigSum };
  });

  let allocated = 0n;
  for (const quota of quotas) {
    allocated += quota.floor;
  }
  const leftover = Number(bigTotal - allocated);

  const order = quotas.map((_, index) => index);
  order.sort((a, b) => {
    const remainderA = quotas[a].remainder;
    const remainderB = quotas[b].remainder;
    if (remainderA !== remainderB) {
      return remainderA > remainderB ? -1 : 1;
    }
    return a - b;
  });

  const result = quotas.map((quota) => quota.floor);
  for (let i = 0; i < leftover; i++) {
    result[order[i]] += 1n;
  }

  return result.map(Number);
