const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function invalid(message) {
  return new RangeError(message);
}

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw invalid("total must be a nonnegative safe integer");
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw invalid("weights must be a nonempty array");
  }

  const bigTotal = BigInt(total);
  let weightSum = 0n;
  const bigWeights = weights.map((weight) => {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw invalid("each weight must be a positive safe integer");
    }
    const bigWeight = BigInt(weight);
    if (bigTotal * bigWeight > MAX_SAFE) {
      throw invalid("total * weight must fit in the safe integer range");
    }
    weightSum += bigWeight;
    return bigWeight;
  });
  if (weightSum > MAX_SAFE) {
    throw invalid("sum of weights must fit in the safe integer range");
  }

  const quotas = bigWeights.map((weight) => (bigTotal * weight) / weightSum);
  const remainders = bigWeights.map((weight) => (bigTotal * weight) % weightSum);

  let leftover = bigTotal;
  for (const quota of quotas) {
    leftover -= quota;
  }

  const order = remainders.map((_, index) => index);
  order.sort((a, b) => {
    if (remainders[a] !== remainders[b]) {
      return remainders[a] > remainders[b] ? -1 : 1;
    }
    return a - b;
  });

  for (let i = 0; i < leftover; i++) {
    quotas[order[i]] += 1n;
  }

  return quotas.map(Number);
}

