  for (const w of ws) sum += w;
  if (sum > MAX_SAFE) {
    throw new RangeError('sum of weights exceeds the safe integer range');
  }
  for (const w of ws) {
    if (t * w > MAX_SAFE) {
      throw new RangeError('total * weight exceeds the safe integer range');
    }
  }

  const shares = ws.map((w) => (t * w) / sum);
  const remainders = ws.map((w) => (t * w) % sum);

  let assigned = 0n;
  for (const share of shares) assigned += share;
  const leftover = Number(t - assigned);

  const order = weights.map((_, index) => index);
  order.sort((a, b) => {
    if (remainders[a] !== remainders[b]) {
      return remainders[a] > remainders[b] ? -1 : 1;
    }
    return a - b;
  });
  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1n;
  }

  return shares.map(Number);
}

