import re
from datetime import datetime, timedelta, timezone

_TIMESTAMP = re.compile(
    r"(?P<year>[0-9]{4})-(?P<month>[0-9]{2})-(?P<day>[0-9]{2})"
    r"T(?P<hour>[0-9]{2}):(?P<minute>[0-9]{2}):(?P<second>[0-9]{2})"
    r"(?:\.[0-9]{1,6})?"
    r"(?:Z|(?P<sign>[+-])(?P<offset_hour>[0-9]{2}):(?P<offset_minute>[0-5][0-9]))"
)


def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    match = _TIMESTAMP.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}")
    offset = timedelta(0)
    if match["sign"] is not None:
        offset = timedelta(hours=int(match["offset_hour"]), minutes=int(match["offset_minute"]))
        if match["sign"] == "-":
            offset = -offset
    try:
        instant = datetime(
            int(match["year"]),
            int(match["month"]),
            int(match["day"]),
            int(match["hour"]),
            int(match["minute"]),
            int(match["second"]),
            tzinfo=timezone(offset),
        )
        utc = instant.astimezone(timezone.utc)
    except (ValueError, OverflowError):
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from None
    return datetime(utc.year, utc.month, utc.day, tzinfo=timezone.utc)

