import re
from datetime import datetime, timedelta, timezone

_TIMESTAMP = re.compile(
    r"(?P<year>[0-9]{4})-(?P<month>[0-9]{2})-(?P<day>[0-9]{2})"
    r"T(?P<hour>[0-9]{2}):(?P<minute>[0-9]{2})"
    r"(?::(?P<second>[0-9]{2})(?:\.(?P<fraction>[0-9]{1,6}))?)?"
    r"(?P<offset>Z|[+-][0-9]{2}:[0-9]{2})"
)


def _parse(text):
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    match = _TIMESTAMP.fullmatch(text)
    if match is None:
        raise ValueError(
            f"expected ISO 8601 timestamp with explicit Z or +HH:MM/-HH:MM offset: {text!r}"
        )

    fraction = match["fraction"] or ""
    microsecond = int(fraction.ljust(6, "0")) if fraction else 0

    offset = match["offset"]
    if offset == "Z":
        tzinfo = timezone.utc
    else:
        hours = int(offset[1:3])
        minutes = int(offset[4:6])
        if hours > 23 or minutes > 59:
            raise ValueError(f"UTC offset out of range: {offset!r}")
        sign = -1 if offset[0] == "-" else 1
        tzinfo = timezone(sign * timedelta(hours=hours, minutes=minutes))

    return datetime(
        int(match["year"]),
        int(match["month"]),
        int(match["day"]),
        int(match["hour"]),
        int(match["minute"]),
        int(match["second"] or 0),
        microsecond,
        tzinfo=tzinfo,
    )


def utc_day_start(text):
    instant = _parse(text)
    try:
        utc = instant.astimezone(timezone.utc)
    except OverflowError as exc:
        raise ValueError(f"timestamp out of range once converted to UTC: {text!r}") from exc
    return datetime(utc.year, utc.month, utc.day, tzinfo=timezone.utc)

