from solution import decode_chunks  # noqa: E402


class DecodeChunksTest(unittest.TestCase):
    def test_empty_iterable(self):
        self.assertEqual(decode_chunks([]), "")

    def test_empty_chunks_are_ignored(self):
        self.assertEqual(decode_chunks([b"", b"a", b"", b"b", b""]), "ab")

    def test_ascii_single_chunk(self):
        self.assertEqual(decode_chunks([b"hello"]), "hello")

    def test_two_byte_character_split_across_chunks(self):
        # "é" is C3 A9
        self.assertEqual(decode_chunks([b"caf\xc3", b"\xa9"]), "café")

    def test_four_byte_character_split_across_three_chunks(self):
        # "😀" is F0 9F 98 80
        self.assertEqual(
            decode_chunks([b"\xf0", b"\x9f\x98", b"\x80"]), "\U0001F600"
        )

    def test_every_split_point_of_mixed_text(self):
        text = "aé€\U0001F600z"
        data = text.encode("utf-8")
        for i in range(len(data) + 1):
            with self.subTest(split=i):
                self.assertEqual(decode_chunks([data[:i], data[i:]]), text)

    def test_one_byte_chunks(self):
        text = "naïve ☃ 😀"
        data = text.encode("utf-8")
        self.assertEqual(decode_chunks(bytes([b]) for b in data), text)

    def test_accepts_generator(self):
        def gen():
            yield "héllo".encode("utf-8")[:2]
            yield "héllo".encode("utf-8")[2:]

        self.assertEqual(decode_chunks(gen()), "héllo")

    def test_incomplete_final_character_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"abc", b"\xe2\x82"])

    def test_incomplete_final_character_in_single_chunk_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xf0\x9f\x98"])

    def test_invalid_byte_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"ok", b"\xff", b"more"])

    def test_invalid_continuation_across_chunks_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xc3", b"("])

    def test_encoded_surrogate_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xed\xa0\x80"])


