const VERSION_PATTERN = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/;

function parseVersion(version, name) {
  if (typeof version !== 'string' || !VERSION_PATTERN.test(version)) {
    throw new TypeError(`${name} must be a version string of three dot-separated decimal integers`);
  }
  return version.split('.').map(BigInt);
}

function compareVersion(a, b) {
  const left = parseVersion(a, 'a');
  const right = parseVersion(b, 'b');
  for (let i = 0; i < 3; i++) {
    if (left[i] !== right[i]) {
      return left[i] < right[i] ? -1 : 1;
    }
  }
  return 0;
}

module.exports = { compareVersion };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { compareVersion } = require('../src/solution.cjs');

test('compares components numerically, not lexically', () => {
  assert.equal(compareVersion('1.10.0', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.9', '1.10.0'), -1);
});

test('orders by major, then minor, then patch', () => {
  assert.equal(compareVersion('2.0.0', '1.9.9'), 1);
  assert.equal(compareVersion('1.9.9', '2.0.0'), -1);
  assert.equal(compareVersion('1.3.0', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.10', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.9', '1.2.10'), -1);
});

test('returns 0 for equal versions', () => {
  assert.equal(compareVersion('0.0.0', '0.0.0'), 0);
  assert.equal(compareVersion('1.2.3', '1.2.3'), 0);
  assert.equal(compareVersion('10.20.30', '10.20.30'), 0);
});

test('handles components beyond Number.MAX_SAFE_INTEGER', () => {
  const safeMax = String(Number.MAX_SAFE_INTEGER);
  const beyond = '9007199254740993';
  assert.equal(compareVersion(`${beyond}.0.0`, `${safeMax}.0.0`), 1);
  assert.equal(compareVersion(`${safeMax}.0.0`, `${beyond}.0.0`), -1);
  assert.equal(compareVersion(`1.${beyond}.0`, '1.9007199254740992.0'), 1);
  assert.equal(compareVersion('1.0.9007199254740993', '1.0.9007199254740992'), 1);
});

test('compares huge components of different lengths', () => {
  assert.equal(compareVersion('10000000000000000000.0.0', '999999999999999999999.0.0'), -1);
  assert.equal(compareVersion('123456789012345678901234567890.1.2', '123456789012345678901234567890.1.2'), 0);
  assert.equal(compareVersion('123456789012345678901234567891.0.0', '123456789012345678901234567890.999.999'), 1);
});

test('accepts zero components', () => {
  assert.equal(compareVersion('0.0.1', '0.0.0'), 1);
  assert.equal(compareVersion('0.1.0', '0.0.9'), 1);
});

test('throws TypeError for non-string input', () => {
  for (const value of [undefined, null, 123, 1.2, ['1', '2', '3'], {}]) {
    assert.throws(() => compareVersion(value, '1.0.0'), TypeError);
    assert.throws(() => compareVersion('1.0.0', value), TypeError);
  }
});

test('throws TypeError for malformed strings', () => {
  const malformed = [
    '',
    '1',
    '1.2',
    '1.2.3.4',
    '1..3',
    '.1.2.3',
    '1.2.3.',
    '1.2.-3',
    '-1.2.3',
    '+1.2.3',
    ' 1.2.3',
    '1.2.3 ',
    '1.2.3\n',
