class Emitter {
  #events = new Map();

  on(event, fn) {
    let records = this.#events.get(event);
    if (!records) {
      records = [];
      this.#events.set(event, records);
    }

    let record = records.find((r) => r.fn === fn);
    if (!record) {
      record = { fn };
      records.push(record);
    }

    return () => this.#remove(event, record);
  }

  off(event, fn) {
    const records = this.#events.get(event);
    if (!records) return;

    const record = records.find((r) => r.fn === fn);
    if (record) this.#remove(event, record);
  }

  emit(event, value) {
    const records = this.#events.get(event);
    if (!records) return;

    for (const record of records.slice()) {
      record.fn(value);
    }
  }

  #remove(event, record) {
    const records = this.#events.get(event);
    if (!records) return;

    const index = records.indexOf(record);
    if (index === -1) return;

    records.splice(index, 1);
    if (records.length === 0) this.#events.delete(event);
  }
}

