class Emitter {
  #events = new Map();

  on(event, fn) {
    let list = this.#events.get(event);
    if (!list) {
      list = [];
      this.#events.set(event, list);
    }

    const existing = list.find((entry) => entry.fn === fn);
    if (existing) return existing.unsubscribe;

    const entry = { fn, unsubscribe: null };
    entry.unsubscribe = () => this.#remove(event, entry);
    list.push(entry);
    return entry.unsubscribe;
  }

  off(event, fn) {
    const list = this.#events.get(event);
    if (!list) return;

    const entry = list.find((candidate) => candidate.fn === fn);
    if (entry) this.#remove(event, entry);
  }

  emit(event, value) {
    const list = this.#events.get(event);
    if (!list) return;

    for (const entry of list.map((candidate) => candidate.fn)) {
      entry(value);
    }
  }

  #remove(event, entry) {
    const list = this.#events.get(event);
    if (!list) return;

    const index = list.indexOf(entry);
    if (index === -1) return;

    list.splice(index, 1);
    if (list.length === 0) this.#events.delete(event);
  }
}

