class Emitter {
  #events = new Map();

  on(event, fn) {
    const subs = this.#subscriptions(event);
    const existing = subs.find((sub) => sub.fn === fn);
    if (existing) return existing.unsubscribe;

    const sub = {
      fn,
      unsubscribe: () => {
        const current = this.#events.get(event);
        if (!current || !current.includes(sub)) return;
        current.splice(current.indexOf(sub), 1);
        if (current.length === 0) this.#events.delete(event);
      },
    };
    subs.push(sub);
    return sub.unsubscribe;
  }

  emit(event, value) {
    const subs = this.#events.get(event);
    if (!subs) return;
    for (const sub of [...subs]) sub.fn(value);
  }

  off(event, fn) {
    const subs = this.#events.get(event);
    if (!subs) return;
    const sub = subs.find((s) => s.fn === fn);
    if (sub) sub.unsubscribe();
  }

  #subscriptions(event) {
    let subs = this.#events.get(event);
    if (!subs) {
      subs = [];
      this.#events.set(event, subs);
    }
    return subs;
  }
}

