class Emitter {
  #events = new Map();

  on(event, fn) {
    let registrations = this.#events.get(event);
    if (!registrations) {
      registrations = [];
      this.#events.set(event, registrations);
    }

    let registration = registrations.find((r) => r.fn === fn);
    if (!registration) {
      const record = { fn, unsubscribe: null };
      record.unsubscribe = () => this.#remove(event, record);
      registration = record;
      registrations.push(registration);
    }
    return registration.unsubscribe;
  }

  off(event, fn) {
    const registrations = this.#events.get(event);
    const registration = registrations?.find((r) => r.fn === fn);
    if (registration) this.#remove(event, registration);
  }

  emit(event, value) {
    const registrations = this.#events.get(event);
    if (!registrations) return;
    for (const { fn } of registrations.slice()) {
      fn(value);
    }
  }

  #remove(event, registration) {
    const registrations = this.#events.get(event);
    if (!registrations) return;
    const index = registrations.indexOf(registration);
    if (index === -1) return;
    registrations.splice(index, 1);
    if (registrations.length === 0) this.#events.delete(event);
  }
}

