class Emitter {
  #listeners = new Map();

  on(event, fn) {
    let entries = this.#listeners.get(event);
    if (!entries) {
      entries = [];
      this.#listeners.set(event, entries);
    }
    if (entries.some((entry) => entry.fn === fn)) {
      return () => {};
    }

    const entry = { fn };
    entries.push(entry);
    return () => {
      const current = this.#listeners.get(event);
      if (!current) return;
      const index = current.indexOf(entry);
      if (index !== -1) current.splice(index, 1);
    };
  }

  off(event, fn) {
    const entries = this.#listeners.get(event);
    if (!entries) return;
    const index = entries.findIndex((entry) => entry.fn === fn);
    if (index !== -1) entries.splice(index, 1);
  }

  emit(event, value) {
    const entries = this.#listeners.get(event);
    if (!entries) return;
    for (const { fn } of entries.slice()) {
      fn(value);
    }
  }
}

