class Emitter {
  #events = new Map();

  on(event, fn) {
    const entries = this.#events.get(event) ?? [];
    this.#events.set(event, entries);
    let entry = entries.find((e) => e.fn === fn);
    if (!entry) {
      entry = { fn };
      entries.push(entry);
    }
    return () => this.#remove(event, entry);
  }

  off(event, fn) {
    const entry = this.#events.get(event)?.find((e) => e.fn === fn);
    if (entry) this.#remove(event, entry);
  }

  emit(event, value) {
    const entries = this.#events.get(event);
    if (!entries) return;
    for (const fn of entries.map((e) => e.fn)) fn(value);
  }

  #remove(event, entry) {
    const entries = this.#events.get(event);
    if (!entries) return;
    const index = entries.indexOf(entry);
    if (index === -1) return;
    entries.splice(index, 1);
    if (entries.length === 0) this.#events.delete(event);
  }
}

