class Emitter {
  #events = new Map();

  on(event, fn) {
    let entries = this.#events.get(event);
    if (!entries) {
      entries = [];
      this.#events.set(event, entries);
    }
    if (entries.some((entry) => entry.fn === fn)) {
      return () => {};
    }
    const entry = { fn };
    entries.push(entry);
    return () => {
      const index = entries.indexOf(entry);
      if (index !== -1) entries.splice(index, 1);
    };
  }

  off(event, fn) {
    const entries = this.#events.get(event);
    if (!entries) return;
    const index = entries.findIndex((entry) => entry.fn === fn);
    if (index !== -1) entries.splice(index, 1);
  }

  emit(event, value) {
    const entries = this.#events.get(event);
    if (!entries) return;
    for (const entry of entries.slice()) {
      entry.fn(value);
    }
  }
}

