'use strict';

class Emitter {
  constructor() {
    this._events = new Map();
  }

  on(event, fn) {
    let records = this._events.get(event);
    if (!records) {
      records = [];
      this._events.set(event, records);
    }
    let record = records.find((r) => r.fn === fn);
    if (!record) {
      record = { fn, active: true };
      records.push(record);
    }
    return () => this._remove(event, record);
  }

  off(event, fn) {
    const records = this._events.get(event);
    if (!records) return;
    const record = records.find((r) => r.fn === fn);
    if (record) this._remove(event, record);
  }

  emit(event, value) {
    const records = this._events.get(event);
    if (!records) return;
    for (const { fn } of records.slice()) {
      fn(value);
    }
  }

  _remove(event, record) {
    if (!record.active) return;
    record.active = false;
    const records = this._events.get(event);
    records.splice(records.indexOf(record), 1);
    if (records.length === 0) this._events.delete(event);
  }
}

