export type Result<T> =
  | { ok: true; value: T }
  | { ok: false; error: string };

export function mapResult<T, U>(r: Result<T>, fn: (value: T) => U): Result<U> {
  if (r.ok) {
    return { ok: true, value: fn(r.value) };
  }
  return r;
}

export function unwrapOr<T>(r: Result<T>, fallback: T): T {
  if (r.ok) {
    return r.value;
  }
  return fallback;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { mapResult, unwrapOr, type Result } from "../src/solution.ts";

const ok = <T>(value: T): Result<T> => ({ ok: true, value });
const fail = <T>(error: string): Result<T> => ({ ok: false, error });

test("mapResult applies fn to a success value", () => {
  const r = mapResult(ok(2), (n: number) => n * 10);
  assert.deepEqual(r, { ok: true, value: 20 });
});

test("mapResult can change the value type", () => {
  const r = mapResult(ok(42), (n: number) => String(n));
  assert.deepEqual(r, { ok: true, value: "42" });
});

test("mapResult does not call fn on failure and returns the failure unchanged", () => {
  let calls = 0;
  const input: Result<number> = fail("boom");
  const r = mapResult(input, (n: number) => {
    calls += 1;
    return n + 1;
  });
  assert.equal(calls, 0);
  assert.equal(r, input);
});

test("mapResult propagates exceptions thrown by fn", () => {
  assert.throws(
    () =>
      mapResult(ok(1), () => {
        throw new RangeError("bad");
      }),
    RangeError,
  );
});

