import tempfile
import unittest
from pathlib import Path

from src.solution import resolve_upload


class ResolveUploadTests(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        base = Path(tmp.name).resolve()
        self.root = base / "root"
        self.sibling = base / "root_sibling"
        self.outside = base / "outside"
        for directory in (self.root, self.sibling, self.outside):
            directory.mkdir()
        (self.root / "sub").mkdir()
        (self.root / "sub" / "file.txt").write_text("inside")
        (self.sibling / "secret.txt").write_text("sibling")
        (self.outside / "secret.txt").write_text("outside")
        (self.root / "link_dir").symlink_to(self.sibling)
        (self.root / "link_file").symlink_to(self.outside / "secret.txt")
        (self.root / "link_inner").symlink_to(self.root / "sub")
        (self.root / "dangling").symlink_to(self.outside / "missing.txt")
        (self.root / "self").symlink_to(self.root)

    def test_accepts_existing_file(self):
        self.assertEqual(
            resolve_upload(self.root, "sub/file.txt"),
            self.root / "sub" / "file.txt",
        )

    def test_accepts_nested_nonexistent_path_without_creating_it(self):
        result = resolve_upload(self.root, "a/b/new.txt")
        self.assertEqual(result, self.root / "a" / "b" / "new.txt")
        self.assertFalse((self.root / "a").exists())

    def test_accepts_dotdot_that_stays_inside(self):
        self.assertEqual(
            resolve_upload(self.root, "sub/../sub/file.txt"),
            self.root / "sub" / "file.txt",
        )

    def test_accepts_symlink_that_stays_inside(self):
        self.assertEqual(
            resolve_upload(self.root, "link_inner/file.txt"),
            self.root / "sub" / "file.txt",
        )

    def test_returns_path_instance(self):
        self.assertIsInstance(resolve_upload(str(self.root), "x.txt"), Path)

    def test_rejects_absolute_path(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, str(self.outside / "secret.txt"))

    def test_rejects_target_equal_to_root(self):
        for supplied in ("", ".", "sub/..", "self"):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_rejects_parent_traversal(self):
        for supplied in ("../outside/secret.txt", "sub/../../outside/secret.txt"):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_rejects_sibling_sharing_name_prefix(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "../root_sibling/new.txt")

    def test_rejects_symlinked_directory_pointing_outside(self):
        for supplied in ("link_dir/secret.txt", "link_dir/new.txt"):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_rejects_symlinked_file_pointing_outside(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link_file")

    def test_rejects_dangling_symlink_pointing_outside(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "dangling")


if __name__ == "__main__":
    unittest.main()

